sql.if:
AND (

    (
        h.lease_mode_id = #{item.leaseModeId, jdbcType=BIGINT}
        AND h.building = #{item.building, jdbcType=VARCHAR}
        AND h.unit = #{item.unit, jdbcType=VARCHAR}
        AND h.floor = #{item.floor, jdbcType=INTEGER}
        )

)

mapper.select:
SELECT CASE WHEN DATEDIFF(CURDATE(), DATE(r.vacancy_start_at)) BETWEEN 0 AND 7 THEN 'vacancy_1_7' WHEN DATEDIFF(CURDATE(), DATE(r.vacancy_start_at)) BETWEEN 8 AND 15 THEN 'vacancy_8_15' ELSE 'vacancy_gt_15' END AS `key`, COUNT(*) AS `count` FROM room r LEFT JOIN house h ON r.house_id = h.id WHERE r.deleted = 0 AND r.occupancy_status = 0 AND IFNULL(r.closed, 0) = 0 AND IFNULL(r.locked, 0) = 0 AND r.vacancy_start_at IS NOT NULL
AND h.lease_mode = #{leaseMode}
GROUP BY CASE WHEN DATEDIFF(CURDATE(), DATE(r.vacancy_start_at)) BETWEEN 0 AND 7 THEN 'vacancy_1_7' WHEN DATEDIFF(CURDATE(), DATE(r.vacancy_start_at)) BETWEEN 8 AND 15 THEN 'vacancy_8_15' ELSE 'vacancy_gt_15' END

SELECT COUNT(1)
FROM room
WHERE house_id = #{houseId}
  AND room_number = #{roomNumber}
  AND deleted = 0

      AND id != #{excludeRoomId}

SELECT COUNT(1) FROM owner_contract_subject s JOIN owner_contract c ON c.id = s.contract_id AND c.deleted = 0 WHERE s.deleted = 0 AND c.status IN
#{item}
AND ( (s.subject_type = 'HOUSE' AND s.subject_id = #{houseId}) OR (s.subject_type = 'FOCUS' AND #{leaseMode} = 1 AND s.subject_id = #{leaseModeId}) OR ( s.subject_type = 'FOCUS_BUILDING' AND #{leaseMode} = 1 AND EXISTS ( SELECT 1 FROM focus_building fb WHERE fb.id = s.subject_id AND fb.deleted = 0 AND fb.focus_id = #{leaseModeId} AND fb.building = #{building} AND (fb.unit = #{unit} OR (fb.unit IS NULL AND #{unit} IS NULL)) ) ) )
